import{_ as e,c as n,aU as o,a as r}from"./chunks/framework.DIXiA2XH.js";const u=JSON.parse('{"title":"Redis","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/mianshi/Redis.md","filePath":"note/back-end/mianshi/Redis.md","lastUpdated":1784375236000}'),t={name:"note/back-end/mianshi/Redis.md"};function a(i,s,l,d,p,g){return r(),n("div",null,[...s[0]||(s[0]=[o(`<h1 id="redis" tabindex="-1">Redis <a class="header-anchor" href="#redis" aria-label="Permalink to &quot;Redis&quot;">​</a></h1><h2 id="redis的淘汰策略" tabindex="-1">redis的淘汰策略 <a class="header-anchor" href="#redis的淘汰策略" aria-label="Permalink to &quot;redis的淘汰策略&quot;">​</a></h2><p>LRU 淘汰策略，当内存使用量达到maxmemory限制时,Redis会从所有键中选择最近最少使用的键(LRU,Least Recently Used)进行淘汰</p><h2 id="redis的持久化" tabindex="-1">redis的持久化 <a class="header-anchor" href="#redis的持久化" aria-label="Permalink to &quot;redis的持久化&quot;">​</a></h2><p>Redis是内存数据库，所有数据都存储在内存中。为了避免进程退出导致数据丢失，Redis提供了将内存中的数据持久化到磁盘上的机制。这样在下次重启时，就可以从磁盘恢复数据。</p><p>Redis主要有两种持久化方式：RDB和AOF。</p><h3 id="rdb" tabindex="-1">RDB <a class="header-anchor" href="#rdb" aria-label="Permalink to &quot;RDB&quot;">​</a></h3><p>RDB持久化是指在指定的时间间隔内，将内存中的数据集快照（Snapshot） 写入磁盘。它生成一个压缩的二进制文件（默认名为 dump.rdb）</p><p>工作原理：</p><ul><li>创建快照：Redis会fork出一个子进程。</li><li>子进程负责：将整个内存中的数据序列化并写入一个临时的RDB文件。</li><li>替换旧文件：当子进程完成写操作后，会用这个新的RDB文件替换旧的RDB文件。</li></ul><p><strong>手动触发:</strong></p><ul><li>SAVE命令：同步执行，会阻塞所有客户端请求，直到RDB文件创建完毕。生产环境几乎不用。</li><li>BGSAVE命令：异步执行，后台fork子进程来创建RDB文件，主进程继续提供服务。生产环境常用</li></ul><p><strong>自动触发</strong>：在配置文件 redis.conf 中设置，例如：(一般为自动触发)</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>save 900 1      # 在900秒（15分钟）内，至少有1个key发生变化</span></span>
<span class="line"><span>save 300 10     # 在300秒（5分钟）内，至少有10个key发生变化</span></span>
<span class="line"><span>save 60 10000   # 在60秒（1分钟）内，至少有10000个key发生变化</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>满足任意一个条件，就会自动触发BGSAVE。</p><p><strong>优点</strong></p><ul><li><strong>性能高，恢复速度快</strong>：RDB是数据的紧凑快照，非常适合用于<strong>备份、灾难恢复</strong>和<strong>快速重启</strong>。</li><li><strong>最大化Redis性能</strong>：<code>fork</code>子进程进行持久化，对主进程影响较小。</li><li><strong>文件紧凑</strong>：二进制格式，文件体积小。</li></ul><p><strong>缺点</strong></p><ul><li><strong>数据安全性低</strong>：容易丢失最后一次快照之后的数据。根据配置，可能会丢失几分钟的数据。</li><li><strong><code>fork</code>可能阻塞</strong>：如果数据集非常大，<code>fork</code>子进程的过程可能会耗时较长，导致主进程短暂阻塞（毫秒级或秒级，取决于硬件和数据集大小）。</li></ul><h3 id="aof" tabindex="-1">AOF <a class="header-anchor" href="#aof" aria-label="Permalink to &quot;AOF&quot;">​</a></h3><p>AOF持久化以<strong>日志形式</strong>记录每一个<strong>写操作命令</strong>（例如<code>SET</code>, <code>SADD</code>, <code>LPUSH</code>），并将这些命令追加到AOF文件的末尾。当Redis重启时，会<strong>重放（replay）</strong> AOF文件中的所有命令来重建数据集。</p><p><strong>工作原理</strong></p><ol><li><strong>命令追加（Append）</strong>：所有写命令在执行后都会被追加到服务器内部的<code>aof_buf</code>缓冲区。</li><li><strong>文件写入（Write）</strong> &amp; <strong>同步（Sync）</strong>：根据配置的<strong>appendfsync</strong>策略，将缓冲区的内容写入和同步到磁盘的AOF文件。</li><li><strong>文件重写（Rewrite）</strong>：为了避免AOF文件无限膨胀，Redis会定期根据当前内存中的数据<strong>重建</strong>一个更小的AOF文件（例如，对于一个key的100次<code>INCR</code>操作，重写后只需记录一条<code>SET key 100</code>的命令）。</li></ol><p><strong><code>appendfsync</code> 策略（核心配置）</strong></p><ul><li><strong>no</strong>：由操作系统决定何时同步。性能最好，但数据安全性最差。</li><li><strong>everysec</strong>（<strong>默认推荐</strong>）：每秒同步一次。是性能和数据安全性的良好折衷，最多丢失1秒的数据。</li><li><strong>always</strong>：每个写命令都同步。数据最安全，但性能最差，会严重降低Redis速度。</li></ul><p><strong>优点</strong></p><ul><li><strong>数据安全性高</strong>：使用<code>everysec</code>策略最多丢失1秒数据；使用<code>always</code>策略则不会丢失任何已确认的写命令。</li><li><strong>可读性强</strong>：AOF文件是纯文本格式，记录了所有操作命令，便于理解和分析。</li><li><strong>自动重写</strong>：通过<code>BGREWRITEAOF</code>命令或自动配置，可以压缩AOF文件。</li></ul><p><strong>缺点</strong></p><ul><li><strong>文件体积大</strong>：通常AOF文件会比同数据集的RDB文件大得多。</li><li><strong>恢复速度慢</strong>：重放所有命令来恢复数据，比RDB要慢。</li><li><strong>性能相对较低</strong>：根据同步策略的不同，性能可能会低于RDB。</li></ul>`,29)])])}const h=e(t,[["render",a]]);export{u as __pageData,h as default};
